-- Base SQL generee a partir du fichier Excel tableau_examens.xlsx
-- Contient le schema + les donnees
-- Compatible MySQL / MariaDB

DROP DATABASE IF EXISTS OR_google_database;
CREATE DATABASE OR_google_database CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE OR_google_database;

CREATE TABLE filaire (
    id_filaire INT PRIMARY KEY,
    code_filaire VARCHAR(50) NOT NULL,
    nom_filaire VARCHAR(150) NOT NULL,
    annee ENUM('1ERE', '2EME', '3EME') NOT NULL,
    UNIQUE KEY uq_filaire (code_filaire, annee)
);

CREATE TABLE proffer (
    id_proffer INT PRIMARY KEY,
    nom_professeur VARCHAR(150) NOT NULL,
    UNIQUE KEY uq_professeur (nom_professeur)
);

CREATE TABLE mataire (
    id_mataire INT PRIMARY KEY,
    nom_mataire VARCHAR(200) NOT NULL,
    id_proffe INT NOT NULL,
    filaire_id INT NOT NULL,
    jour TINYINT NOT NULL,
    type ENUM('DS', 'EXAMEN') NOT NULL,
    CONSTRAINT chk_jour CHECK (jour BETWEEN 1 AND 7),
    CONSTRAINT fk_mataire_proffe FOREIGN KEY (id_proffe) REFERENCES proffer(id_proffer),
    CONSTRAINT fk_mataire_filaire FOREIGN KEY (filaire_id) REFERENCES filaire(id_filaire)
);

